"""Self-contained, lightweight preview of the actual final PNGs (not evidence replacements)."""
from pathlib import Path
from PIL import Image
import base64,hashlib,html,io,json
from views import VIEWS
R=Path(__file__).resolve().parents[2];m=json.loads((R/'evidence/producer/screenshot-manifest.json').read_text());sha=hashlib.sha256((R/'scene/building-final.blend').read_bytes()).hexdigest();tag='buildinglab/blender/candidate-20261016-'+sha[:12];url='https://github.com/dreamer2664/storagecode/releases/tag/'+tag
cards=[]
for v in VIEWS:
 row=next(x for x in m['images'] if x['id']==v['id']);assert row['source_sha256']==sha
 im=Image.open(R/row['path']).convert('RGB');im.thumbnail((1000,563));b=io.BytesIO();im.save(b,format='JPEG',quality=86,optimize=True);data=base64.b64encode(b.getvalue()).decode()
 cards.append(f'<article><a href="{html.escape("../"+row["path"])}"><img loading="lazy" src="data:image/jpeg;base64,{data}" alt="{v["id"]}"></a><div><h2>{v["id"]}</h2><p>{row["width"]} × {row["height"]} · {row["camera"]}</p><code>{row["sha256"][:20]}…</code></div></article>')
body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Casa dei Colori — detailed model</title><style>*{box-sizing:border-box}body{margin:0;background:#f2ede2;color:#173d38;font:16px system-ui,sans-serif}header,footer{padding:40px max(5vw,20px);background:#153d37;color:#faf5e8}header h1{font-size:clamp(32px,6vw,68px);margin:8px 0 16px;font-weight:500;letter-spacing:-2px}header small{letter-spacing:3px}header p{max-width:950px;line-height:1.65}a{color:inherit}header a{display:inline-block;border:1px solid #d9b493;border-radius:5px;padding:10px 16px;margin:8px 8px 0 0;text-decoration:none}main{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;padding:32px max(4vw,18px)}article{background:#fffaf1;box-shadow:0 2px 12px #173d3815;border-radius:6px;overflow:hidden}article img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#8d99a4}article div{padding:14px 18px 20px}h2{margin:0 0 7px;font-size:19px}article p,code{font-size:12px;margin:0 0 8px;overflow-wrap:anywhere}footer{line-height:1.7}footer code{font-size:12px}@media(max-width:700px){main{grid-template-columns:1fr}header{padding:30px 20px}}</style><header><small>ORIGINAL ARCHITECTURE / DETAILED RELEASE CANDIDATE</small><h1>Casa dei Colori</h1><p>Six occupied levels · fourteen furnished homes · café, reception and shared spaces · two stairs and lift · metric editable geometry. These are lightweight previews of actual Blender evidence, not generated-image substitutes. Download the verified release for the native, portable GLB, all 29 full-resolution PNGs, plans, schedules, sources, rights and review records.</p>'''
body+=f'<a href="{url}">Release / full-resolution package</a><a href="../HANDOFF.md">Detailed handoff</a><a href="../scene/building-final.blend">Native .blend</a><a href="../exports/building-final.glb">Portable .glb</a><p><strong>Independent acceptance: pending.</strong> Producer inspection and mechanical tests are not non-owner approval. Conceptual architecture, not engineered or code-approved.</p></header><main>'+''.join(cards)+f'</main><footer>Native source SHA-256<br><code>{sha}</code><p>Preview images are reduced JPEGs embedded for offline viewing; required evidence is the original PNGs in renders/final. Local file links work after extracting the complete release in a normal browser. This in-app preview may restrict navigation/download links.</p></footer></html>'
(R/'renders/GALLERY.html').write_text(body);print('SELF_CONTAINED_GALLERY',len(cards),'actual-render previews',len(body),'bytes')
